<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';
$bulan=(string)($_GET['bulan']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$bulan))$bulan=date('Y-m');$kelasId=(int)($_GET['kelas_id']??0);$sholatId=(int)($_GET['sholat_id']??0);$perPage=(int)($_GET['per_page']??20);if(!in_array($perPage,[10,20,50,100],true))$perPage=20;$page=max(1,(int)($_GET['page']??1));
$kelas=$pdo->query("SELECT id,nama,tingkat,urutan FROM master_kelas WHERE aktif=1 ORDER BY tingkat,urutan,nama")->fetchAll();$sholats=$pdo->query("SELECT id,nama FROM jenis_sholat WHERE aktif=1 ORDER BY urutan,nama")->fetchAll();
$where=["s.status='aktif'","sa.tanggal LIKE ?"]; $params=[$bulan.'%'];if($kelasId>0){$where[]='mk.id=?';$params[]=$kelasId;}if($sholatId>0){$where[]='sa.jenis_sholat_id=?';$params[]=$sholatId;}$ws=implode(' AND ',$where);
$sql="SELECT s.id,s.nis,s.nama,s.jk,mk.nama nama_kelas,COUNT(DISTINCT sa.id) sesi,COALESCE(SUM(ash.status='SUDAH'),0) sudah,COALESCE(SUM(ash.status='BERHALANGAN'),0) berhalangan,COALESCE(SUM(ash.id IS NULL),0) belum FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id LEFT JOIN sesi_absensi sa ON sa.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sa.tanggal LIKE ? AND sa.jenis_absensi_id=(SELECT id FROM jenis_absensi WHERE kategori='sholat' ORDER BY id LIMIT 1) LEFT JOIN absensi_sholat ash ON ash.sesi_id=sa.id AND ash.siswa_id=s.id WHERE s.status='aktif'";
// Build with selected filters against joined rows.
$sql="SELECT s.id,s.nis,s.nama,s.jk,mk.nama nama_kelas,COUNT(DISTINCT sa.id) sesi,COALESCE(SUM(ash.status='SUDAH'),0) sudah,COALESCE(SUM(ash.status='BERHALANGAN'),0) berhalangan,COALESCE(SUM(ash.id IS NULL),0) belum FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id LEFT JOIN sesi_absensi sa ON sa.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sa.tanggal LIKE ? AND sa.jenis_absensi_id=(SELECT id FROM jenis_absensi WHERE kategori='sholat' ORDER BY id LIMIT 1) LEFT JOIN absensi_sholat ash ON ash.sesi_id=sa.id AND ash.siswa_id=s.id WHERE s.status='aktif'";
$params=[$bulan.'%'];if($kelasId>0){$sql.=' AND mk.id=?';$params[]=$kelasId;}if($sholatId>0){$sql.=' AND sa.jenis_sholat_id=?';$params[]=$sholatId;}$sql.=' GROUP BY s.id,s.nis,s.nama,s.jk,mk.nama ORDER BY COALESCE(mk.urutan,9999),s.nama';$countSql='SELECT COUNT(*) FROM ('.$sql.') AS q';$countSt=$pdo->prepare($countSql);$countSt->execute($params);$total=(int)$countSt->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));if($page>$totalPages)$page=$totalPages;$offset=($page-1)*$perPage;$st=$pdo->prepare($sql.' LIMIT '.(int)$perPage.' OFFSET '.(int)$offset);$st->execute($params);$rows=$st->fetchAll();
$page_title='Rekap Absensi Sholat';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Rekap Absensi Sholat</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content sholat-submodule"><div class="page-header"><div><h1>Rekap Absensi Sholat</h1><p>Rekap bulanan per siswa/kelas. Status Berhalangan tidak dihitung sebagai Belum.</p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>sholat/index.php">Kembali</a></div></div><div class="dashboard-table-card"><form method="get" class="filter-bar"><input class="form-control" type="month" name="bulan" value="<?=e($bulan)?>"><select class="form-control" name="kelas_id"><option value="0">Semua kelas</option><?php foreach($kelas as $k):?><option value="<?=$k['id']?>" <?=$kelasId===(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select><select class="form-control" name="sholat_id"><option value="0">Semua sholat aktif</option><?php foreach($sholats as $j):?><option value="<?=$j['id']?>" <?=$sholatId===(int)$j['id']?'selected':''?>><?=e($j['nama'])?></option><?php endforeach;?></select><select class="form-control" name="per_page"><option value="10" <?=$perPage===10?'selected':''?>>10</option><option value="20" <?=$perPage===20?'selected':''?>>20</option><option value="50" <?=$perPage===50?'selected':''?>>50</option><option value="100" <?=$perPage===100?'selected':''?>>100</option></select><button class="btn btn-secondary">Tampilkan</button></form><div class="table-responsive"><table class="data-table"><thead><tr><th>No.</th><th>Siswa</th><th>Kelas</th><th>Sesi</th><th>Sudah</th><th>Belum</th><th>Berhalangan</th></tr></thead><tbody><?php $no=1;foreach($rows as $r):?><tr><td><?=$no++?></td><td><strong><?=e($r['nama'])?></strong><br><small><?=e($r['nis'])?></small></td><td><?=e($r['nama_kelas']??'-')?></td><td><?= (int)$r['sesi']?></td><td><?= (int)$r['sudah']?></td><td><?= (int)$r['belum']?></td><td><?= (int)$r['berhalangan']?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-state">Tidak ada data.</td></tr><?php endif;?></tbody></table></div><div class="pagination-bar"><div class="text-muted">Menampilkan <?=$total?($offset+1).'–'.min($offset+$perPage,$total):'0'?> dari <?=$total?> siswa</div><div class="pagination"><?php for($pg=1;$pg<=$totalPages;$pg++):?><a class="btn btn-sm <?=$pg===$page?'btn-primary':'btn-secondary'?>" href="?bulan=<?=rawurlencode($bulan)?>&kelas_id=<?=$kelasId?>&sholat_id=<?=$sholatId?>&per_page=<?=$perPage?>&page=<?=$pg?>"><?=$pg?></a><?php endfor;?></div></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
